        bool isFizz = (i % 3 == 0);
        bool isBuzz = (i % 5 == 0);

        if (isFizz && isBuzz)
        {
            result[i - 1] = "FizzBuzz";
        }
        else if (isFizz)
        {
            result[i - 1] = "Fizz";
        }
        else if (isBuzz)
        {
            result[i - 1] = "Buzz";
        }
        else
        {
            result[i - 1] = i.ToString();
        }
    }

    return result;
