using System;
using System.Collections.Generic;

public class IntervalMerger
{
    public static int[][] MergeIntervals(int[][] intervals)
    {
        if (intervals == null || intervals.Length == 0)
        {
            return new int[0][];
        }

        // Sort by start time using Array.Sort with a custom Comparison
        Array.Sort(intervals, delegate(int[] a, int[] b)
        {
            return a[0].CompareTo(b[0]);
        });

        List<int[]> merged = new List<int[]>();
        int[] current = intervals[0];
        merged.Add(current);

        for (int i = 1; i < intervals.Length; i++)
        {
            int[] next = intervals[i];

            // If next start is <= current end, they overlap or touch
            if (next[0] <= current[1])
            {
                // Update current end if next end is larger
                if (next[1] > current[1])
                {
                    current[1] = next[1];
                }
            }
            else
            {
                // No overlap, move to next interval
                current = next;
                merged.Add(current);
            }
        }

        return merged.ToArray();
    }
}
