using System;
using System.Collections.Generic;
using System.Text.RegularExpressions;

public static class TextProcessor
{
    public static Dictionary<string, int> WordFrequency(string text)
    {
        var counts = new Dictionary<string, int>();

        if (string.IsNullOrEmpty(text))
        {
            return counts;
        }

        // Regex matches runs of letters, digits, or apostrophes
        // \w includes underscores; to strictly match letters/digits/apostrophes per requirements:
        // We use a pattern that targets the specific allowed characters.
        MatchCollection matches = Regex.Matches(text, @"[a-zA-Z0-9']+");

        foreach (Match match in matches)
        {
            string word = match.Value.ToLower();

            if (counts.ContainsKey(word))
            {
                counts[word]++;
            }
            else
            {
                counts.Add(word, 1);
            }
        }

        return counts;
    }
}
