using System;
using System.Text;
using System.Text.RegularExpressions;

public static class StringExtensions
{
    public static string ToSnakeCase(string name)
    {
        if (string.IsNullOrEmpty(name))
        {
            return name;
        }

        StringBuilder result = new StringBuilder();
        int i = 0;
        int length = name.Length;

        while (i < length)
        {
            char current = name[i];

            if (i > 0 && char.IsUpper(current))
            {
                // Check if we need an underscore:
                // 1. Previous char was lowercase (e.g., 'aB' -> 'a_b')
                // 2. Current char is uppercase AND next char is lowercase (e.g., 'HB' in 'XMLHttp' -> 'xml_http')
                bool prevIsLower = char.IsLower(name[i - 1]) || char.IsDigit(name[i - 1]);
                bool nextIsLower = (i + 1 < length) && char.IsLower(name[i + 1]);

                if (prevIsLower || nextIsLower)
                {
                    result.Append('_');
                }
            }

            result.Append(char.ToLowerInvariant(current));
            i++;
        }

        return result.ToString();
    }
}
