    param(
        [Parameter(Mandatory = $true)]
        [string[]]$Path
    )

    $counts = @{}

    foreach ($item in $Path) {
        $extension = ""

        if (Test-Path -Path $item -PathType Leaf) {
            $ext = [System.IO.Path]::GetExtension($item)
            if (-not [string]::IsNullOrEmpty($ext)) {
                $extension = $ext.TrimStart('.').ToLowerInvariant()
            }
        }

        $counts[$extension] = [int]$counts[$extension] + 1
    }

    return $counts
}
