function Get-Median {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [double[]]$Values
    )

    if ($Values.Count -eq 0) {
        return $null
    }

    $sorted = $Values | Sort-Object
    $count = $sorted.Count
    $middle = [math]::Floor($count / 2)

    if ($count % 2 -ne 0) {
        return [double]$sorted[$middle]
    }
    else {
        return [double]($sorted[$middle - 1] + $sorted[$middle]) / 2.0
    }
}
