    param(
        [Parameter(Mandatory = $true)]
        [string]$Text
    )

    $hash = @{}
    $pairs = $Text -split ';'

    foreach ($pair in $pairs) {
        if ($pair -match '^(.*?)=(.*)$') {
            $key = $Matches[1].Trim()
            $value = $Matches[2].Trim()

            if (-not [string]::IsNullOrWhiteSpace($key)) {
                $hash[$key] = $value
            }
        }
    }

    return $hash
}
