function Get-Fibonacci {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [int]$Count
    )

    if ($Count -le 0) {
        return
    }

    $results = New-Object System.Collections.Generic.List[long]

    for ($i = 0; $i -lt $Count; $i++) {
        if ($i -eq 0) {
            $results.Add(0L)
        }
        elseif ($i -eq 1) {
            $results.Add(1L)
        }
        else {
            $next = $results[$i - 1] + $results[$i - 2]
            $results.Add($next)
        }
    }

    return $results
}
