function Get-WeekdayCount {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [datetime]$Start,

        [Parameter(Mandatory = $true)]
        [datetime]$End
    )

    if ($End -lt $Start) {
        return 0
    }

    $count = 0
    $current = $Start.Date

    while ($current -le $End.Date) {
        $dayOfWeek = $current.DayOfWeek
        if ($dayOfWeek -ne 'Saturday' -and $dayOfWeek -ne 'Sunday') {
            $count++
        }
        $current = $current.AddDays(1)
    }

    return $count
}
